using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using System.Net;using System.Net.Http.Json;using System.Text.Json;using System.Security.Cryptography;
namespace Decont.Tests;
public class DocumentIntakeTests {
 static readonly byte[] Png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a16kAAAAASUVORK5CYII=");
 static async Task<HttpClient> Login(Factory f,string name){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{username=name,password="Valid-test-Password1!"})).StatusCode);csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return c;}
 static void Key(HttpClient c,string? key=null){c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",key??Guid.NewGuid().ToString());}
 static async Task<Guid> Report(Factory f,string state=States.Draft){using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var r=new Report{EmployeeId=(await db.Users.SingleAsync(u=>u.UserName=="alice")).Id,ManagerId=(await db.Users.SingleAsync(u=>u.UserName=="manager")).Id,Purpose="Signed intake",State=state};db.Reports.Add(r);await db.SaveChangesAsync();return r.Id;}
 static BundleRequest Request(long version=1)=>new(version,"receipt.png",Png.Length,"image/png",Convert.ToHexString(SHA256.HashData(Png)));
 static async Task<JsonElement> Intent(HttpClient c,Guid report){Key(c);var response=await c.PostAsJsonAsync($"/api/reports/{report}/document-bundles",Request());Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());return await response.Content.ReadFromJsonAsync<JsonElement>();}
 static async Task<HttpResponseMessage> Content(HttpClient c,Guid report,JsonElement grant,byte[]? bytes=null){c.DefaultRequestHeaders.Remove("X-Upload-Token");c.DefaultRequestHeaders.Add("X-Upload-Token",grant.GetProperty("token").GetString());using var form=new MultipartFormDataContent();form.Add(new StringContent("1"),"version");form.Add(new StringContent("Finance review"),"reason");form.Add(new ByteArrayContent(bytes??Png),"file","receipt.png");return await c.PostAsync("/api"+grant.GetProperty("uploadUrl").GetString(),form);}
 [Fact]public async Task SignedUploadDoesNotQueueScanningUntilCompletionAndCanResume(){await using var f=new Factory();await f.Seed();var id=await Report(f);var alice=await Login(f,"alice");var grant=await Intent(alice,id);var document=grant.GetProperty("documentId").GetGuid();Key(alice);var response=await Content(alice,id,grant);Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var source=await db.ReportAttachments.SingleAsync();Assert.Equal("AwaitingCompletion",source.Scan);Assert.True(source.Capture);Assert.Equal(Convert.ToHexString(SHA256.HashData(Png)),source.Hash);Assert.False(await db.Jobs.AnyAsync(j=>j.Kind=="ScanReport"));}Key(alice);var auth=await alice.PostAsJsonAsync($"/api/reports/{id}/document-bundles/{document}/authorization",new VersionRequest(2,null));Assert.True(auth.IsSuccessStatusCode,await auth.Content.ReadAsStringAsync());var renewed=await auth.Content.ReadFromJsonAsync<JsonElement>();var key=Guid.NewGuid().ToString();var input=new BundleComplete(2,renewed.GetProperty("token").GetString()!);Key(alice,key);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{id}/document-bundles/{document}/complete",input)).StatusCode);Key(alice,key);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{id}/document-bundles/{document}/complete",input)).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Equal("Pending",(await db.ReportAttachments.SingleAsync()).Scan);Assert.Equal(1,await db.Jobs.CountAsync(j=>j.Kind=="ScanReport"));}}
 [Fact]public async Task AuthorisationIsBoundToUserReportAndContent(){await using var f=new Factory();await f.Seed();var id=await Report(f);var alice=await Login(f,"alice");var bob=await Login(f,"bob");var grant=await Intent(alice,id);Key(bob);Assert.Equal(HttpStatusCode.Forbidden,(await Content(bob,id,grant)).StatusCode);Key(alice);var other=await Report(f);alice.DefaultRequestHeaders.Remove("X-Upload-Token");alice.DefaultRequestHeaders.Add("X-Upload-Token",grant.GetProperty("token").GetString());using(var form=new MultipartFormDataContent()){form.Add(new StringContent("1"),"version");form.Add(new ByteArrayContent(Png),"file","receipt.png");Assert.Equal(HttpStatusCode.Forbidden,(await alice.PostAsync($"/api/reports/{other}/document-bundles/{grant.GetProperty("documentId").GetGuid()}/content",form)).StatusCode);}Key(alice);Assert.Equal(HttpStatusCode.Conflict,(await Content(alice,id,grant,Png.Concat(new byte[]{1}).ToArray())).StatusCode);using var scope=f.Services.CreateScope();Assert.Empty(await scope.ServiceProvider.GetRequiredService<Db>().ReportAttachments.ToListAsync());}
 [Fact]public async Task IntakeRespectsFinancePermissionsAndDeclaredLimits(){await using var f=new Factory();await f.Seed();var id=await Report(f,States.Finance);var alice=await Login(f,"alice");var finance=await Login(f,"finance");Key(alice);Assert.Equal(HttpStatusCode.Forbidden,(await alice.PostAsJsonAsync($"/api/reports/{id}/document-bundles",Request())).StatusCode);Key(finance);var accepted=await finance.PostAsJsonAsync($"/api/reports/{id}/document-bundles",Request() with{Reason="Review original receipt"});Assert.True(accepted.IsSuccessStatusCode,await accepted.Content.ReadAsStringAsync());Key(finance);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await finance.PostAsJsonAsync($"/api/reports/{id}/document-bundles",Request() with{Reason="Review original receipt",Size=Files.MaxFile+1})).StatusCode);Key(finance);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await finance.PostAsJsonAsync($"/api/reports/{id}/document-bundles",Request() with{Reason="Review original receipt",Mime="text/html"})).StatusCode);}

 [Fact]public async Task InvalidTokenAndNullMetadataProduceControlledErrors(){await using var f=new Factory();await f.Seed();var id=await Report(f);var c=await Login(f,"alice");Key(c);var invalid=await c.PostAsJsonAsync($"/api/reports/{id}/document-bundles/{Guid.NewGuid()}/complete",new BundleComplete(1,"invalid-token"));Assert.Equal(HttpStatusCode.Forbidden,invalid.StatusCode);Key(c);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await c.PostAsJsonAsync($"/api/reports/{id}/document-bundles",Request() with{Name=null!})).StatusCode);}
}

